<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav aria-label="Site navigation">
      <a href="index.html">Welcome</a>
      <a href="services.html">Offerings</a>
      <a href="conditions.html">Conditions</a>
      <a href="approach.html">Our Way</a>
      <a href="pricing.html">Rates</a>
      <a href="about.html" style="color:var(--accent)">Meet</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="intro reveal-on-scroll">
      <h1>Who we are</h1>
      <p class="byline">A small collective focused on practical, integrative support — blending evidence, lifestyle, and human stories to help people feel steadier in their days.</p>
      <div style="margin-top:12px;display:flex;gap:10px">
        <button class="btn" style="background:var(--accent);color:white;padding:10px 14px;border-radius:8px;border:0;cursor:pointer" id="open-modal">Try a mini practice</button>
        <a href="book.html" style="text-decoration:none;color:var(--accent);padding:10px 12px;border-radius:8px;border:1px solid rgba(123,111,176,0.15);align-self:center">Schedule a visit</a>
      </div>
    </section>

    <section class="story reveal-on-scroll" style="margin-top:22px">
      <h2>Our approach</h2>
      <p class="story">We begin with curiosity. Instead of checking boxes, we ask: how does this fit into the life you already live? From there we co-create modest experiments — small, measurable things you can try between visits. Over time those experiments become habits that reflect what matters most.</p>
    </section>

    <section class="reveal-on-scroll" style="margin-top:22px">
      <h2>The team</h2>
      <div class="team">
        <div class="person">
          <h4>Lead clinician</h4>
          <div class="muted">A thoughtful clinician trained in integrative approaches, with a focus on practical plans for busy adults.</div>
          <p class="story">They pair listening with a pragmatic checklist of small steps — dietary shifts, rhythm changes, and simple behavioral experiments — designed for real life.</p>
        </div>
        <div class="person">
          <h4>Health coach</h4>
          <div class="muted">A coach who helps translate plans into daily routines and reflections.</div>
          <p class="story">Through gentle accountability and resource curating, they support progress between visits with short guidance and clear tools.</p>
      </div>
      </div>
    </section>

    <section style="margin-top:22px" class="reveal-on-scroll">
      <h2>Why this matters</h2>
      <p class="story">Many people find medical visits helpful for diagnosis but hard to translate into daily changes. We focus on translation: turning insight into a manageable sequence of moves that fit work, family, and rest.</p>
    </section>

  </main>

  <footer>
    <div style="max-width:900px;margin:0 auto;padding:20px;color:var(--muted);font-size:13px;display:flex;justify-content:space-between;align-items:center">
      <div>Questions? <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      <div>{{BUSINESS_NAME}} — <span class="muted">Call</span> {{PHONE}}</div>
    </div>
  </footer>

  <!-- Reuse modal (breathing/journaling) -->
  <div id="modal" class="modal-backdrop" role="dialog" aria-modal="true" aria-hidden="true" style="display:none;align-items:center;justify-content:center;padding:20px;background:rgba(10,10,10,0.35)">
    <div class="modal" style="max-width:640px;padding:18px">
      <header style="display:flex;justify-content:space-between;align-items:center">
        <strong>Try a mini practice</strong>
        <button class="close" id="close-modal" aria-label="Close">✕</button>
      </header>
      <div style="margin-top:12px">
        <p class="muted">Short techniques to notice and shift energy. Choose one below.</p>
        <div style="display:flex;gap:8px;margin-top:8px">
          <button class="btn" data-practice="breath">Breathing</button>
          <button class="btn ghost" data-practice="journ">Journaling</button>
          <button class="btn ghost" data-practice="intend">Set intention</button>
        </div>
        <div id="practice-area" style="margin-top:12px;color:var(--muted)">Select a practice to begin.</div>
      </div>
    </div>
  </div>

  <script>
    (function(){
      'use strict';
      // Lightweight modal & practices (same behaviors as pricing to keep local JS only)
      var modal = document.getElementById('modal');
      var open = document.getElementById('open-modal');
      var close = document.getElementById('close-modal');
      var practiceArea = document.getElementById('practice-area');
      function prefersReduced(){return window.matchMedia('(prefers-reduced-motion: reduce)').matches}
      open.addEventListener('click', function(){ modal.style.display='flex'; modal.setAttribute('aria-hidden','false'); });
      close.addEventListener('click', function(){ modal.style.display='none'; modal.setAttribute('aria-hidden','true'); stopTimers(); });
      modal.addEventListener('click', function(e){ if(e.target===modal) { modal.style.display='none'; stopTimers(); } });
      var timers=[]; function stopTimers(){ timers.forEach(clearInterval); timers=[] }
