{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Schedule — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Book a session or request an intake form.">
  <style>
    :root{--bg:#f9fbfa;--muted:#596162;--accent:#d46b6b;--card:#ffffff}
    *{box-sizing:border-box}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#202020;background:var(--bg)}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;background:white;border-bottom:1px solid rgba(0,0,0,0.04)}
    nav a{color:var(--muted);text-decoration:none;margin-left:16px}
    .wrap{max-width:920px;margin:34px auto;padding:0 20px}
    .grid{display:grid;grid-template-columns:1fr 340px;gap:20px}
    .panel{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 10px 30px rgba(22,22,22,0.04)}
    .muted{color:var(--muted)}
    label{display:block;margin-top:10px;font-weight:600}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(0,0,0,0.06);margin-top:6px}
    .btn{background:var(--accent);color:white;padding:10px 14px;border-radius:8px;border:0;cursor:pointer;font-weight:700}

    .reveal-on-scroll{opacity:0;transform:translateY(18px);transition:opacity .6s ease,transform .6s ease}
    .reveal-on-scroll.revealed{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal-on-scroll{transition:none;opacity:1;transform:none}}

    .calendar-sample{display:flex;flex-direction:column;gap:8px}
    .slot{padding:10px;border-radius:8px;border:1px solid rgba(0,0,0,0.04);display:flex;justify-content:space-between;align-items:center}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div style="width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,#f4b6b6,#d46b6b);display:grid;place-items:center;color:white;font-weight:700">HM</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Welcome</a>
      <a href="services.html">Offerings</a>
      <a href="conditions.html">Conditions</a>
      <a href="approach.html">Our Way</a>
      <a href="pricing.html">Rates</a>
      <a href="about.html">Meet</a>
      <a href="book.html" style="color:var(--accent)">Schedule</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <div class="grid">
      <div class="panel reveal-on-scroll">
        <h2 style="margin:0">Book a visit</h2>
        <p class="muted" style="margin-top:8px">Choose a visit type and tell us a bit about what you'd like to focus on. We'll reply with available times and a short intake form.</p>
        <form id="booking-form" style="margin-top:12px">
          <label for="name">Your name</label>
          <input id="name" name="name" placeholder="First and last" required>

          <label for="email">Email</label>
          <input id="email" name="email" type="email" placeholder="you@example.com" required>

          <label for="type">Visit type</label>
          <select id="type" name="type">
            <option>Clarity Visit (20 min)</option>
            <option>Foundations Session (60 min)</option>
            <option>Rhythm Program (4-session cycle)</option>
          </select>

          <label for="notes">Primary question or concern</label>
          <textarea id="notes" name="notes" placeholder="A few sentences about what you'd like to work on"></textarea>

          <div style="display:flex;gap:10px;margin-top:12px">
            <button class="btn" type="submit">Request times</button>
            <button id="quick-call" type="button" style="background:transparent;border:1px solid rgba(212,107,107,0.14);color:var(--accent);padding:10px 12px;border-radius:8px">Request phone call</button>
          </div>
        </form>
        <p class="muted" style="margin-top:10px">If you prefer to book by phone, call <strong>{{PHONE}}</strong> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
      </div>

      <aside class="panel reveal-on-scroll">
        <h3 style="margin-top:0">Available slots (sample)</h3>
        <div class="calendar-sample">
          <div class="slot"><div>Mon 10:00 AM</div><div class="muted">Clarity</div></div>
          <div class="slot"><div>Tue 2:00 PM</div><div class="muted">Foundations</div></div>
          <div class="slot"><div>Thu 9:00 AM</div><div class="muted">Foundations</div></div>
          <div class="slot"><div>Fri 11:30 AM</div><div class="muted">Clarity</div></div>
        </div>

        <h4 style="margin-top:14px">Before your visit</h4>
        <p class="muted">We’ll send a short intake and a few reflection prompts. These help visits focus on immediate, practical changes rather than long lists of tests.</p>

        <div style="margin-top:12px">
          <button id="open-modal" class="btn" style="width:100%">Try a mini practice</button>
        </div>
      </aside>
    </div>

    <section style="margin-top:18px" class="reveal-on-scroll">
      <h3>Questions about scheduling</h3>
      <p class="muted">If you need evening or weekend options, include your availability in the notes. We try to be flexible and can sometimes offer brief consults between standard hours. For insurance, we provide documentation but do not bill insurers directly.</p>
    </section>

  </main>

  <footer style="max-width:920px;margin:40px auto;padding:20px;color:var(--muted);font-size:13px">
    <div style="display:flex;justify-content:space-between;align-items:center">
      <div>{{BUSINESS_NAME}} — <span class="muted">Contact</span> <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      <div class="muted">Phone: {{PHONE}}</div>
    </div>
  </footer>

  <!-- Modal for practices reused locally -->
  <div id="modal" class="modal-backdrop" role="dialog" aria-modal="true" aria-hidden="true" style="display:none;align-items:center;justify-content:center;padding:20px;background:rgba(10,10,10,0.35)">
    <div class="modal" style="max-width:640px;padding:18px;background:white;border-radius:12px">
      <header style="display:flex;justify-content:space-between;align-items:center">
        <strong>Try a mini practice</strong>
        <button class="close" id="close-modal" aria-label="Close">✕</button>
      </header>
      <div style="margin-top:12px">
        <p class="muted">Practice a short technique now.</p>
        <div style="display:flex;gap:8px;margin-top:8px">
          <button class="btn" data-practice="breath">Breathing</button>
          <button class="btn ghost" data-practice="journ">Journaling</button>
          <button class="btn ghost" data-practice="intend">Set intention</button>
        </div>
        <div id="practice-area" style="margin-top:12px;color:var(--muted)">Select a practice to begin.</div>
      </div>
    </div>
  </div>

  <script>
    (function(){
      'use strict';
      // Form submit mock
      var form = document.getElementById('booking-form');
      form.addEventListener('submit', function(e){ e.preventDefault(); alert('Thanks — we will reply with available times at ' + (document.getElementById('email').value || '{{EMAIL}}') ); form.reset(); });

      document.getElementById('quick-call').addEventListener('click', function(){ alert('We will call you shortly. If urgent, please phone ' + '{{PHONE}}'); });

      // Modal reuse
      var modal = document.getElementById('modal');
      var openBtns = document.querySelectorAll('#open-modal');
      var close = document.getElementById('close-modal');
      var practiceArea = document.getElementById('practice-area');

      function prefersReduced(){ return window.matchMedia('(prefers-reduced-motion: reduce)').matches }

      openBtns.forEach(function(b){ b.addEventListener('click', function(){ modal.style.display='flex'; modal.setAttribute('aria-hidden','false'); }); });
      close.addEventListener('click', function(){ modal.style.display='none'; modal.setAttribute('aria-hidden','true'); stopTimers(); });
      modal.addEventListener('click', function(e){ if(e.target===modal){ modal.style.display='none'; stopTimers(); } });

      var timers=[]; function stopTimers(){ timers.forEach(clearInterval); timers=[] }
      document.querySelectorAll('[data-practice]').forEach(function(btn){ btn.addEventListener('click', function(){ var which=btn.getAttribute('data-practice'); stopTimers(); if(which==='breath') startBreathing(); if(which==='journ') startJournaling(); if(which==='intend') startIntention(); }) });

      function startBreathing(){ practiceArea.innerHTML=''; var p=document.createElement('p'); p.className='muted'; p.textContent='Breath: inhale 4 / hold 2 / exhale 6 for 60 seconds.'; var timer=document.createElement('div'); timer.style.fontWeight='700'; timer.style.marginTop='8px'; var remaining=60; timer.textContent=remaining+'s'; practiceArea.appendChild(p); practiceArea.appendChild(timer); if(prefersReduced()){ timer.textContent='A short minute of breathing recommended'; return } timers.push(setInterval(function(){ remaining--; if(remaining<=0){ clearInterval(timers.pop()); timer.textContent='Completed.'; return } timer.textContent=remaining+'s'; },1000)); }
      function startJournaling(){ practiceArea.innerHTML=''; var p=document.createElement('p'); p.className='muted'; p.textContent='Write for two minutes on a small win from today.'; var ta=document.createElement('textarea'); ta.style.width='100%'; ta.style.height='110px'; ta.style.marginTop='8px'; practiceArea.appendChild(p); practiceArea.appendChild(ta); var remaining=120; var timer=document.createElement('div'); timer.style.fontWeight='700'; timer.style.marginTop='8px'; timer.textContent=remaining+'s'; practiceArea.appendChild(timer); if(prefersReduced()){ timer.textContent='A short writing prompt suggested'; return } timers.push(setInterval(function(){ remaining--; if(remaining<=0){ clearInterval(timers.pop()); timer.textContent='Complete.'; return } timer.textContent=remaining+'s'; },1000)); }
      function startIntention(){ practiceArea.innerHTML=''; var p=document.createElement('p'); p.className='muted'; p.textContent='Name a brief intention for the next hour.'; var input=document.createElement('input'); input.type='text'; input.style.width='100%'; input.style.marginTop='8px'; var save=document.createElement('button'); save.className='btn'; save.textContent='Save'; save.style.marginTop='8px'; save.addEventListener('click', function(){ if(input.value.trim()){ practiceArea.innerHTML='<div style="font-weight:700;color:var(--accent)">Saved: "'+escapeHtml(input.value.trim())+'"</div>'; } }); practiceArea.appendChild(p); practiceArea.appendChild(input); practiceArea.appendChild(save); }
      function escapeHtml(s){ return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;') }

      // Scroll reveal
      var revealEls = Array.prototype.slice.call(document.querySelectorAll('.reveal-on-scroll'));
      function onScroll(){ if(prefersReduced()){ revealEls.forEach(function(el){ el.classList.add('revealed') }); window.removeEventListener('scroll', onScroll); return } var h=window.innerHeight||document.documentElement.clientHeight; revealEls.forEach(function(el){ var r=el.getBoundingClientRect(); if(r.top < h - 80) el.classList.add('revealed'); }); }
      window.addEventListener('load', onScroll); window.addEventListener('scroll', onScroll);
    })();
  </script>
</body>
</html>"} 
